"""Plan-and-execute agent with replan on failure, plan diffs, and dual budgets.

Conceptual references:
- ./docs/en.md (this lesson)
- Phase 14 lesson 01 (agent loop fundamentals)
- Phase 13 lesson 02 (tool protocols overview)

Stdlib only. Run: python3 code/main.py
"""

from __future__ import annotations

import json
import time
from dataclasses import dataclass, field
from typing import Any, Callable


@dataclass
class Step:
    id: int
    tool_name: str
    args: dict
    expected_outcome: str
    result: Any | None = None
    error: str | None = None

    def signature(self) -> tuple:
        return (self.tool_name, json.dumps(self.args, sort_keys=True))


@dataclass
class PlanDiff:
    revision: int
    removed: list[int]
    added: list[int]
    revised: list[int]

    def to_dict(self) -> dict:
        return {
            "revision": self.revision,
            "removed": list(self.removed),
            "added": list(self.added),
            "revised": list(self.revised),
        }


@dataclass
class Event:
    type: str
    payload: dict
    ts: float = field(default_factory=time.time)


@dataclass
class SessionResult:
    status: str
    reason: str
    history: list[Step]
    revisions: list[PlanDiff]
    events: list[Event]

    def to_dict(self) -> dict:
        return {
            "status": self.status,
            "reason": self.reason,
            "history": [
                {"id": s.id, "tool": s.tool_name, "args": s.args,
                 "result": s.result, "error": s.error}
                for s in self.history
            ],
            "revisions": [r.to_dict() for r in self.revisions],
            "events": [{"type": e.type, "payload": e.payload, "ts": e.ts} for e in self.events],
        }


Planner = Callable[[str, list[Step], str | None], list[Step]]
ToolExecutor = Callable[[str, dict], Any]


class ToolFailure(Exception):
    pass


def _diff_plans(old: list[Step], new: list[Step], revision: int) -> PlanDiff:
    old_ids = {s.id for s in old}
    new_ids = {s.id for s in new}
    removed = sorted(old_ids - new_ids)
    added = sorted(new_ids - old_ids)
    revised: list[int] = []
    old_by_id = {s.id: s for s in old}
    for s in new:
        if s.id in old_ids and old_by_id[s.id].signature() != s.signature():
            revised.append(s.id)
    return PlanDiff(revision=revision, removed=removed, added=added, revised=revised)


class PlanExecuteAgent:
    """Sequential plan executor with replan on failure."""

    def __init__(
        self,
        planner: Planner,
        executor: ToolExecutor,
        *,
        max_steps: int = 12,
        max_replans: int = 5,
    ) -> None:
        self._planner = planner
        self._executor = executor
        self.max_steps = max_steps
        self.max_replans = max_replans
        self._events: list[Event] = []

    def _emit(self, etype: str, payload: dict) -> None:
        self._events.append(Event(type=etype, payload=payload))

    def run(self, goal: str) -> SessionResult:
        self._events = []
        history: list[Step] = []
        revisions: list[PlanDiff] = []
        steps_taken = 0
        replans_used = 0
        last_error: str | None = None

        plan = self._planner(goal, history, None)
        self._emit("plan.commit", {"revision": 0, "steps": _summarize(plan)})

        if not plan:
            self._emit("session.complete", {"reason": "no_plan"})
            return SessionResult(
                status="failed", reason="no_plan",
                history=history, revisions=revisions, events=list(self._events),
            )

        cursor = 0
        revision = 0

        while cursor < len(plan):
            if steps_taken >= self.max_steps:
                self._emit("session.complete", {"reason": "step_budget"})
                return SessionResult(
                    status="failed", reason="step_budget",
                    history=history, revisions=revisions, events=list(self._events),
                )

            step = plan[cursor]
            self._emit("step.start", {"step_id": step.id, "tool": step.tool_name})
            try:
                step.result = self._executor(step.tool_name, step.args)
                self._emit("step.end", {"step_id": step.id, "outcome": "ok"})
                history.append(step)
                cursor += 1
                steps_taken += 1
                continue
            except Exception as exc:
                step.error = f"{type(exc).__name__}: {exc}"
                self._emit("step.end", {"step_id": step.id, "outcome": "error", "error": step.error})
                history.append(step)
                steps_taken += 1
                last_error = step.error

            if replans_used >= self.max_replans:
                self._emit("session.complete", {"reason": "replan_budget"})
                return SessionResult(
                    status="failed", reason="replan_budget",
                    history=history, revisions=revisions, events=list(self._events),
                )

            replans_used += 1
            revision += 1
            new_plan = self._planner(goal, history, last_error)
            self._emit("plan.draft", {"revision": revision, "steps": _summarize(new_plan)})
            if not new_plan:
                self._emit("session.complete", {"reason": "no_plan"})
                return SessionResult(
                    status="failed", reason="no_plan",
                    history=history, revisions=revisions, events=list(self._events),
                )
            diff = _diff_plans(plan[cursor:], new_plan, revision)
            revisions.append(diff)
            self._emit("plan.diff", diff.to_dict())
            plan = new_plan
            cursor = 0
            self._emit("plan.commit", {"revision": revision, "steps": _summarize(plan)})

        self._emit("session.complete", {"reason": "goal_met"})
        return SessionResult(
            status="completed", reason="goal_met",
            history=history, revisions=revisions, events=list(self._events),
        )


def _summarize(plan: list[Step]) -> list[dict]:
    return [{"id": s.id, "tool": s.tool_name, "outcome": s.expected_outcome} for s in plan]


def make_deterministic_planner(fail_step_id: int | None, recovery: str = "route_around") -> Planner:
    """Planner used in the demo and tests.

    When ``fail_step_id`` is given, the planner inserts a ``_force_fail`` marker
    into that step's args on the initial plan. Executors that honor the marker
    raise on that step, exercising the replan path. The marker is removed on the
    revised plan so the route-around can succeed.
    """

    def planner(goal: str, history: list[Step], last_error: str | None) -> list[Step]:
        if last_error is None:
            initial = [
                Step(1, "fetch", {"key": "input"}, "loaded user input"),
                Step(2, "transform", {"mode": "v1"}, "computed v1 form"),
                Step(3, "render", {}, "rendered output"),
                Step(4, "submit", {}, "submitted to backend"),
            ]
            if fail_step_id is not None:
                for s in initial:
                    if s.id == fail_step_id:
                        s.args = {**s.args, "_force_fail": True}
            return initial
        if recovery == "route_around" and "transform" in last_error:
            return [
                Step(2, "transform", {"mode": "v2"}, "computed via fallback"),
                Step(3, "render", {}, "rendered output"),
                Step(4, "submit", {}, "submitted to backend"),
            ]
        if recovery == "give_up":
            return [
                Step(98, "log_failure", {"why": last_error or ""}, "logged failure"),
                Step(99, "notify_user", {}, "told the user"),
            ]
        return []

    return planner


def _demo() -> None:
    counters = {"transform_v1_calls": 0}

    def executor(tool: str, args: dict) -> Any:
        if args.get("_force_fail"):
            counters["transform_v1_calls"] += 1
            raise ToolFailure(f"{tool} marker-forced failure")
        if tool == "fetch":
            return {"k": "v"}
        if tool == "transform":
            if args.get("mode") == "v1":
                counters["transform_v1_calls"] += 1
                raise ToolFailure("transform v1 backend down")
            return {"ok": True}
        if tool == "render":
            return "html"
        if tool == "submit":
            return {"id": 1}
        if tool in ("log_failure", "notify_user"):
            return "logged"
        raise ToolFailure(f"unknown tool {tool}")

    agent = PlanExecuteAgent(
        planner=make_deterministic_planner(fail_step_id=2, recovery="route_around"),
        executor=executor,
        max_steps=12, max_replans=5,
    )
    res = agent.run("ship the report")
    print(json.dumps({
        "status": res.status,
        "reason": res.reason,
        "history": [(s.id, s.tool_name, bool(s.error)) for s in res.history],
        "revisions": [r.to_dict() for r in res.revisions],
        "events": [e.type for e in res.events],
        "transform_v1_calls": counters["transform_v1_calls"],
    }, indent=2))


if __name__ == "__main__":
    _demo()

// Lesson: Plan-Execute Control Flow (phase 19 / lesson 24)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/19-capstone-projects/24-plan-execute-control-flow/docs/en.md
// Run: npx tsx phases/19-capstone-projects/24-plan-execute-control-flow/code/main.ts

type Args = Record<string, unknown>;

function pyJsonDumpsSorted(value: unknown): string {
  if (value === null || value === undefined) return "null";
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "number" || typeof value === "string") return JSON.stringify(value);
  if (Array.isArray(value)) return "[" + value.map(pyJsonDumpsSorted).join(", ") + "]";
  const obj = value as Record<string, unknown>;
  const keys = Object.keys(obj).sort();
  return "{" + keys.map((k) => `${JSON.stringify(k)}: ${pyJsonDumpsSorted(obj[k])}`).join(", ") + "}";
}

export class Step {
  result: unknown = null;
  error: string | null = null;
  constructor(
    public id: number,
    public toolName: string,
    public args: Args,
    public expectedOutcome: string,
  ) {}

  signature(): string {
    return JSON.stringify([this.toolName, pyJsonDumpsSorted(this.args)]);
  }
}

export class PlanDiff {
  constructor(
    public revision: number,
    public removed: number[],
    public added: number[],
    public revised: number[],
  ) {}

  toDict(): Record<string, unknown> {
    return {
      revision: this.revision,
      removed: [...this.removed],
      added: [...this.added],
      revised: [...this.revised],
    };
  }
}

export class Event {
  ts: number;
  constructor(public type: string, public payload: Record<string, unknown>) {
    this.ts = Date.now() / 1000;
  }
}

export class SessionResult {
  constructor(
    public status: string,
    public reason: string,
    public history: Step[],
    public revisions: PlanDiff[],
    public events: Event[],
  ) {}

  toDict(): Record<string, unknown> {
    return {
      status: this.status,
      reason: this.reason,
      history: this.history.map((s) => ({
        id: s.id, tool: s.toolName, args: s.args,
        result: s.result, error: s.error,
      })),
      revisions: this.revisions.map((r) => r.toDict()),
      events: this.events.map((e) => ({ type: e.type, payload: e.payload, ts: e.ts })),
    };
  }
}

export type Planner = (goal: string, history: Step[], lastError: string | null) => Step[];
export type ToolExecutor = (tool: string, args: Args) => unknown;

export class ToolFailure extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ToolFailure";
  }
}

function diffPlans(old: Step[], next: Step[], revision: number): PlanDiff {
  const oldIds = new Set(old.map((s) => s.id));
  const newIds = new Set(next.map((s) => s.id));
  const removed = [...oldIds].filter((i) => !newIds.has(i)).sort((a, b) => a - b);
  const added = [...newIds].filter((i) => !oldIds.has(i)).sort((a, b) => a - b);
  const revised: number[] = [];
  const oldById = new Map(old.map((s) => [s.id, s] as [number, Step]));
  for (const s of next) {
    if (oldIds.has(s.id) && oldById.get(s.id)!.signature() !== s.signature()) revised.push(s.id);
  }
  return new PlanDiff(revision, removed, added, revised);
}

export class PlanExecuteAgent {
  private planner: Planner;
  private executor: ToolExecutor;
  maxSteps: number;
  maxReplans: number;
  private events: Event[] = [];

  constructor(
    planner: Planner,
    executor: ToolExecutor,
    opts: { maxSteps?: number; maxReplans?: number } = {},
  ) {
    this.planner = planner;
    this.executor = executor;
    this.maxSteps = opts.maxSteps ?? 12;
    this.maxReplans = opts.maxReplans ?? 5;
  }

  private emit(etype: string, payload: Record<string, unknown>): void {
    this.events.push(new Event(etype, payload));
  }

  run(goal: string): SessionResult {
    this.events = [];
    const history: Step[] = [];
    const revisions: PlanDiff[] = [];
    let stepsTaken = 0;
    let replansUsed = 0;
    let lastError: string | null = null;

    let plan = this.planner(goal, history, null);
    this.emit("plan.commit", { revision: 0, steps: summarize(plan) });

    if (plan.length === 0) {
      this.emit("session.complete", { reason: "no_plan" });
      return new SessionResult("failed", "no_plan", history, revisions, [...this.events]);
    }

    let cursor = 0;
    let revision = 0;

    while (cursor < plan.length) {
      if (stepsTaken >= this.maxSteps) {
        this.emit("session.complete", { reason: "step_budget" });
        return new SessionResult("failed", "step_budget", history, revisions, [...this.events]);
      }

      const step = plan[cursor];
      this.emit("step.start", { step_id: step.id, tool: step.toolName });
      try {
        step.result = this.executor(step.toolName, step.args);
        this.emit("step.end", { step_id: step.id, outcome: "ok" });
        history.push(step);
        cursor += 1;
        stepsTaken += 1;
        continue;
      } catch (exc) {
        const name = exc instanceof Error ? exc.name : "Exception";
        const msg = exc instanceof Error ? exc.message : String(exc);
        step.error = `${name}: ${msg}`;
        this.emit("step.end", { step_id: step.id, outcome: "error", error: step.error });
        history.push(step);
        stepsTaken += 1;
        lastError = step.error;
      }

      if (replansUsed >= this.maxReplans) {
        this.emit("session.complete", { reason: "replan_budget" });
        return new SessionResult("failed", "replan_budget", history, revisions, [...this.events]);
      }

      replansUsed += 1;
      revision += 1;
      const newPlan = this.planner(goal, history, lastError);
      this.emit("plan.draft", { revision, steps: summarize(newPlan) });
      if (newPlan.length === 0) {
        this.emit("session.complete", { reason: "no_plan" });
        return new SessionResult("failed", "no_plan", history, revisions, [...this.events]);
      }
      const diff = diffPlans(plan.slice(cursor), newPlan, revision);
      revisions.push(diff);
      this.emit("plan.diff", diff.toDict());
      plan = newPlan;
      cursor = 0;
      this.emit("plan.commit", { revision, steps: summarize(plan) });
    }

    this.emit("session.complete", { reason: "goal_met" });
    return new SessionResult("completed", "goal_met", history, revisions, [...this.events]);
  }
}

function summarize(plan: Step[]): Record<string, unknown>[] {
  return plan.map((s) => ({ id: s.id, tool: s.toolName, outcome: s.expectedOutcome }));
}

export function makeDeterministicPlanner(failStepId: number | null, recovery: string = "route_around"): Planner {
  return (goal: string, history: Step[], lastError: string | null): Step[] => {
    if (lastError === null) {
      const initial = [
        new Step(1, "fetch", { key: "input" }, "loaded user input"),
        new Step(2, "transform", { mode: "v1" }, "computed v1 form"),
        new Step(3, "render", {}, "rendered output"),
        new Step(4, "submit", {}, "submitted to backend"),
      ];
      if (failStepId !== null) {
        for (const s of initial) {
          if (s.id === failStepId) s.args = { ...s.args, _force_fail: true };
        }
      }
      return initial;
    }
    if (recovery === "route_around" && lastError.includes("transform")) {
      return [
        new Step(2, "transform", { mode: "v2" }, "computed via fallback"),
        new Step(3, "render", {}, "rendered output"),
        new Step(4, "submit", {}, "submitted to backend"),
      ];
    }
    if (recovery === "give_up") {
      return [
        new Step(98, "log_failure", { why: lastError || "" }, "logged failure"),
        new Step(99, "notify_user", {}, "told the user"),
      ];
    }
    return [];
  };
}

function demo(): void {
  const counters = { transform_v1_calls: 0 };

  const executor = (tool: string, args: Args): unknown => {
    if (args._force_fail) {
      counters.transform_v1_calls += 1;
      throw new ToolFailure(`${tool} marker-forced failure`);
    }
    if (tool === "fetch") return { k: "v" };
    if (tool === "transform") {
      if (args.mode === "v1") {
        counters.transform_v1_calls += 1;
        throw new ToolFailure("transform v1 backend down");
      }
      return { ok: true };
    }
    if (tool === "render") return "html";
    if (tool === "submit") return { id: 1 };
    if (tool === "log_failure" || tool === "notify_user") return "logged";
    throw new ToolFailure(`unknown tool ${tool}`);
  };

  const agent = new PlanExecuteAgent(
    makeDeterministicPlanner(2, "route_around"),
    executor,
    { maxSteps: 12, maxReplans: 5 },
  );
  const res = agent.run("ship the report");
  console.log(JSON.stringify({
    status: res.status,
    reason: res.reason,
    history: res.history.map((s) => [s.id, s.toolName, Boolean(s.error)]),
    revisions: res.revisions.map((r) => r.toDict()),
    events: res.events.map((e) => e.type),
    transform_v1_calls: counters.transform_v1_calls,
  }, null, 2));
}

demo();
